NOTE_TEXT = "\n> **本表是索引，不是归口** —— 逐项明细与**状态分类**见\n> [`D-014`](./D-014-未完成任务清单_20261123.md)（§1.2 任务表 ＋ §1.4 四类裁定）\n> 与 [`D-136`](./D-136-剩余任务清单总结与分类裁定_20261125.md)。\n> **读数（2026-11-25 11:45 +08）**：登记二级任务 **22** 个，在盘 **8** 个，已闭合归档 **20** 个（**14** 个 `T-*` ＋ **6** 个历史 `TASK-*`）。\n> 本文件 §3 / §4 / §5 的**横切项合计 55**（性能 **7** ＋ 停止条件 **35** ＋ 归档门槛 **13**）**本轮未变**。\n"


def main() -> None:
    text = mdpatch.read(DOC)
    lines = text.split(NL)
    head = [i for i, line in enumerate(lines) if line.startswith(HEADER)]
    if len(head) != 1:
        raise SystemExit("update_d011: header anchor count %d" % len(head))
    start = head[0]
    tail = [i for i, line in enumerate(lines) if i > start and line.startswith("## ")]
    if not tail:
        raise SystemExit("update_d011: end anchor not found")
    end = tail[0]
    rows = ROWS_TEXT.split(NL)
    while rows and rows[-1] == "":
        rows.pop()
    lines[start:end] = rows + NOTE_TEXT.split(NL) + [""]
    text = NL.join(lines)
    mdpatch.write(DOC, text)
    print("update_d011: ok")


if __name__ == "__main__":
    main()

